-- Generated by scripts/gen_m365_usage_sql.py - edit the generator, not this file.
-- Runs on the Lakehouse SQL endpoint from the M365 Usage Analytics template (m365_usage_sessioncohort).
WITH
r AS (
    SELECT
        LOWER(COALESCE(UserId, '')) AS uid,
        COALESCE(UserId, '') AS UserId,
        COALESCE(LEFT(CreationDate, 10), '') AS dk,
        COALESCE(Operation, '') AS op,
        COALESCE(Workload, '') AS wl,
        LOWER(COALESCE(SourceFileExtension, '')) AS ext,
        LOWER(COALESCE(AppHost, '')) AS host,
        CAST(COALESCE(EventCount, 1) AS BIGINT) AS ec
    FROM dbo.m365_usage_rollup
),
nm AS (
    SELECT uid, MIN(UserId) AS UserId FROM r GROUP BY uid
),
a AS (
    SELECT uid, dk,
        CASE
            WHEN ext IN ('docx', 'doc', 'dotx') AND op IN ('FileAccessed', 'FileModified', 'FileDownloaded', 'FileUploaded') THEN 'Word'
            WHEN ext IN ('xlsx', 'xls', 'xlsm', 'csv') AND op IN ('FileAccessed', 'FileModified', 'FileDownloaded', 'FileUploaded') THEN 'Excel'
            WHEN ext IN ('pptx', 'ppt', 'ppsx') AND op IN ('FileAccessed', 'FileModified', 'FileDownloaded', 'FileUploaded') THEN 'PowerPoint'
            WHEN wl = 'Exchange' AND op IN ('Send', 'MailItemsAccessed', 'MailboxLogin') THEN 'Outlook'
            WHEN wl = 'MicrosoftTeams' AND op IN ('MessageSent', 'MessageRead', 'ChatCreated', 'MeetingParticipantDetail', 'TeamsSessionStarted') THEN 'Teams'
            WHEN wl = 'Copilot' OR op = 'CopilotInteraction' THEN 'Copilot'
            ELSE 'M365 All Apps'
        END AS app
    FROM r
),
s AS (
    SELECT uid, app, COUNT(DISTINCT dk) AS n FROM a WHERE app <> 'M365 All Apps' GROUP BY uid, app
)
SELECT
    nm.UserId,
    s.app AS AppColumn,
    CASE WHEN s.n <= 5 THEN '1-5 sessions'
         WHEN s.n <= 10 THEN '6-10 sessions'
         WHEN s.n <= 20 THEN '11-20 sessions'
         WHEN s.n <= 40 THEN '21-40 sessions'
         WHEN s.n <= 60 THEN '41-60 sessions'
         WHEN s.n <= 80 THEN '61-80 sessions'
         ELSE '81+ sessions' END AS SessionCohort
FROM s
JOIN nm ON nm.uid = s.uid
